INSERT INTO `chat_message` (`id`, `conversation_id`, `role`, `content`, `content_type`, `seq`, `client_msg_id`, `status`, `error_message`, `created_at`) VALUES (52, 17, 'assistant', '你好！我是 TraceMind（溯源大脑）助手，可以帮你核对：\n\n- 质保卡及对应胎号\n- 胎号扫码流水\n- 门店入库、出库及自动补账\n- 连锁门店归属和库存转移\n- 订单、退货及相关业务记录\n\n请告诉我需要查询的车牌号、胎号，或具体业务问题。', 'text', 2, 'srv_010d877b9b8346cf9fb3d6a5fb1321b1', 'normal', '', '2026-10-22 13:55:19');
